27	const PROCESSING_FEE = 5;
28	
29	const BASE_PREMIUMS: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const FIRST_INSURANCE_PERCENT = 10;
39	
40	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
41	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
42	// intermediates to stay exact, so every percentage goes through here.
43	const PERCENT_WHOLE = 100;
44	
45	const percentOf = (amount: number, percent: number): number =>
46	  (amount * percent) / PERCENT_WHOLE;
47	
48	// Rounding always favours MHPCO: premiums round up, payouts round down.
49	const roundPremium = (amount: number): number => Math.ceil(amount);
50	
51	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
52	
53	const BLOCK_SIZE = 3;
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const countByType = (items: Item[]): Map<string, number> => {
57	  const counts = new Map<string, number>();
58	  for (const item of items) {
59	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
60	  }
61	  return counts;
62	};
63	
64	// The policy base premium is the sum of every insured item's base premium,
65	// except that exactly 3 alike components are priced as a block.
66	const policyBasePremiumOf = (items: Item[]): number => {
67	  let total = 0;
68	  for (const [type, count] of countByType(items)) {
69	    total +=
70	      count === BLOCK_SIZE
71	        ? BLOCK_BASE_PREMIUM
72	        : count * basePremiumOf({ type });
73	  }
74	  return total;
75	};
76	
77	const quoteStep = (step: Step): QuoteResult => {
78	  const basePremium = policyBasePremiumOf(step.items);
79	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
80	
81	  return {
82	    premium: roundPremium(
83	      basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
84	    ),
85	  };
86	};
87	
88	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
89	  results: scenario.steps.map(quoteStep),
90	});
