// Exactly 3 alike items are priced as a single block, otherwise each item is
// priced on its own. NOTE: the spec restricts blocks to components (rune,
// moonstone), so 3 swords should *not* block-price. No test demands that yet,
// so the restriction is not implemented — this is where it belongs.
const groupBasePremiumOf = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);

// The policy base premium is the sum of the base premiums of each group of
// alike items.
const policyBasePremiumOf = (items: Item[]): number => {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total += groupBasePremiumOf(type, count);
  }
  return total;
};

